#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "session_render_scene_candidate.h"
#include "film_track_selection_candidate.h"
#include "session_render_root_candidate.h"
#include <iostream>
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("session required");auto g=loadGraph(argv[1]);auto root=sessionRenderRootCandidate(g);for(auto&a:g.elements[root].attributes)if(g.strings.at(a.name)=="mapname")for(auto&v:a.values)std::cout<<"root_mapname="<<v.text<<"\n";auto track=filmClipTrackCandidate(g,root);if(!track)throw std::runtime_error("root film track missing");auto children=hierarchyRefs(g,g.elements[*track],"children",15);for(auto id:children){if(g.strings.at(g.elements[id].type)!="DmeFilmClip")continue;try{auto scene=readSessionRenderSceneCandidate(g,id,512,512);std::cout<<"first_valid_scene_clip="<<id<<" name="<<g.strings.at(g.elements[id].name)<<" models="<<scene.models.size()<<" camera="<<scene.camera<<"\n";for(auto&m:scene.models){std::cout<<"model="<<m.id<<" asset="<<m.placement.asset<<" visible="<<m.visible<<"\n";for(auto&a:g.elements[m.id].attributes){const auto&name=g.strings.at(a.name);if(name=="modelName"||name=="name"||name=="visible"||name=="bones") {std::cout<<" attr="<<name<<" type="<<unsigned(a.type)<<" count="<<a.values.size();if(a.type==5&&!a.values.empty())std::cout<<" text="<<a.values[0].text;std::cout<<"\n";}}auto*a=namedAttribute(g,g.elements[m.id],"bones");if(a)for(size_t n=0;n<std::min<size_t>(a->values.size(),5);++n){auto ref=a->values[n].reference;std::cout<<" saved_bone="<<ref<<":"<<g.strings.at(g.elements[ref].name)<<"\n";}}return scene.models.empty()?2:0;}catch(const std::exception&e){std::cout<<"skip="<<id<<" name="<<g.strings.at(g.elements[id].name)<<" reason="<<e.what()<<"\n";}}throw std::runtime_error("no supported scene clip");}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
